// Local QA fixture only. NO external delivery. Never part of dist or deployment.
import http from 'node:http';
import { handleRequest,DeliveryCoordinator } from '../../server/worker.mjs';
const actors=new Map();let counter=0;
globalThis.fetch=async(url,options)=>{if(url!=='https://api.resend.com/emails')throw Error('External request forbidden by QA fixture');counter++;const body=JSON.parse(options.body);if(body.text.includes('模拟失败'))return new Response('{}',{status:500});return new Response(JSON.stringify({id:'local-qa-only-'+counter}));};
const env={ALLOWED_ORIGINS:'http://127.0.0.1:4173',NOTIFICATION_CHANNELS:'email',IP_HASH_SALT:'local-test-only-not-production',RESEND_API_KEY:'not-real',EMAIL_FROM:'sender@example.test',EMAIL_TO:'recipient@example.test',DELIVERY:{idFromName:x=>x,get(id){if(!actors.has(id)){const map=new Map();let queue=Promise.resolve();const ctx={storage:{get:async k=>structuredClone(map.get(k)),put:async(k,v)=>map.set(k,structuredClone(v)),setAlarm:async()=>{},deleteAll:async()=>map.clear()},blockConcurrencyWhile(fn){const current=queue.then(fn);queue=current.catch(()=>{});return current;}};actors.set(id,new DeliveryCoordinator(ctx,env));}return actors.get(id);}}};
http.createServer(async(req,res)=>{try{const parts=[];for await(const part of req)parts.push(part);const headers=new Headers(req.headers);headers.set('CF-Connecting-IP','192.0.2.5');const response=await handleRequest(new Request('http://127.0.0.1:4174'+req.url,{method:req.method,headers,...(!['GET','HEAD'].includes(req.method)?{body:Buffer.concat(parts)}:{})}),env);res.writeHead(response.status,Object.fromEntries(response.headers));res.end(Buffer.from(await response.arrayBuffer()));}catch{res.writeHead(500);res.end('{}');}}).listen(4174,'127.0.0.1',()=>console.log('LOCAL QA ONLY API at 4174. All email calls are intercepted. No mail sent.'));
